File[] classPath() {
    final String[] classPathElements = System.getProperty("java.class.path").split(File.pathSeparator);
    final List<File> classPathFiles = new ArrayList<>();
    for (String element : classPathElements) {
        File file = new File(element);
        if (file.isFile()) {
            classPathFiles.add(file);
        } else if (file.isDirectory()) {
            classPathFiles.addAll(findFilesInDirectory(file));
        } else {
            LOGGER.warn("Found invalid element in class path: {}", element);
        }
    }
    return classPathFiles.toArray(new File[classPathFiles.size()]);
}

private static List<File> findFilesInDirectory(File directory) {
    List<File> files = new ArrayList<>();
    for (File file : directory.listFiles()) {
        if (file.isFile()) {
            files.add(file);
        } else if (file.isDirectory()) {
            files.addAll(findFilesInDirectory(file));
        } else {
            LOGGER.warn("Found invalid file in directory: {}", file);
        }
    }
    return files;
}

