public static String[] split(String toSplit, String delimiter) {
    if (toSplit == null || delimiter == null) {
        throw new IllegalArgumentException("Input string and delimiter cannot be null");
    }

    if (delimiter.isEmpty()) {
        throw new IllegalArgumentException("Delimiter cannot be an empty string");
    }

    int index = toSplit.indexOf(delimiter);
    if (index == -1) {
        return null;
    }

    String firstPart = toSplit.substring(0, index);
    String secondPart = toSplit.substring(index + delimiter.length());
    return new String[] { firstPart, secondPart };
}

