/**
 * Selects the specified row in the specified JTable and scrolls the specified JScrollPane to the newly selected row.
 * @param row the row to select
 * @param table the JTable that contains the row
 * @param pane the JScrollPane that contains the JTable
 */
public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }

    // Select the specified row in the JTable
    table.setRowSelectionInterval(row, row);

    // Scroll the JScrollPane to the newly selected row
    int cellHeight = table.getCellRect(row, 0, true).height;
    int rowHeight = table.getRowHeight();
    int viewHeight = pane.getViewport().getHeight();
    int verticalPosition = row * rowHeight - viewHeight + cellHeight;
    pane.getViewport().setViewPosition(new Point(0, verticalPosition));

    // Repaint the JScrollPane to ensure the newly selected row is properly displayed
    pane.repaint();
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }

    // Select the row in the table
    table.setRowSelectionInterval(row, row);

    // Scroll the JScrollPane to the newly selected row
    SwingUtilities.invokeLater(() -> {
        Rectangle visibleRect = pane.getViewport().getViewRect();
        Rectangle rowRect = table.getCellRect(row, 0, true);
        pane.getViewport().setViewPosition(new Point(rowRect.x, rowRect.y + rowRect.height / 2 - visibleRect.height / 2));
        pane.repaint();
    });
}

