 * @param keys list of keys.
 * @return the computed key lower bounds.
 */
private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<Integer>();
    for (K key : keys) {
        if (key == null) {
            continue;
        }
        int lowerBound = Integer.MAX_VALUE;
        for (K otherKey : keys) {
            if (otherKey != null && otherKey.compareTo(key) < 0) {
                lowerBound = Math.min(lowerBound, otherKey.compareTo(key));
            }
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

