/**
     * Encodes a string with template parameters names present, specifically the characters '{' and '}' will be percent-encoded.
     * @param s the string with zero or more template parameters names
     * @return the string with encoded template parameters names.
     */
    public static String encodeTemplateNames(String s){
        // initialize the pattern to match the template parameters names
        Pattern pattern = Pattern.compile("\\{+[^}]+\\}+");

        // initialize the matcher with the input string
        Matcher matcher = pattern.matcher(s);

        // if there are no matches, return the input string as is
        if(!matcher.find()){
            return s;
        }

        // initialize a new string builder to hold the encoded string
        StringBuilder encodedString = new StringBuilder();

        // iterate over the matches
        while(matcher.find()){
            // retrieve the matched group
            String group = matcher.group();

            // encode the matched group
            String encodedGroup = URLEncoder.encode(group, "UTF-8");

            // replace the matched group with the encoded group in the original string
            encodedString.append(s.substring(0, matcher.start()));
            encodedString.append(encodedGroup);
            encodedString.append(s.substring(matcher.end()));
        }

        // return the encoded string
        return encodedString.toString();
    }

public static String encodeTemplateNames(String s) {
    Pattern p = Pattern.compile("\\{.*?\\}");
    Matcher m = p.matcher(s);
    List<String> matches = new ArrayList<>();
    while (m.find()) {
        matches.add(m.group(0));
    }
    for (String match : matches) {
        s = s.replace(match, encodeValue(match, "ABNF"));
    }
    return s;
}

