/**
 * Loads thread snapshots in the appointed time range.
 *
 * @param file The file to load thread snapshots from.
 * @param timeRanges The list of time ranges to filter thread snapshots with.
 * @return A list of thread snapshots that fall within the appointed time ranges.
 * @throws IOException If an I/O error occurs during file reading.
 */
public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot threadSnapshot = ThreadSnapshot.parseFromLine(line);
            boolean withinTimeRange = timeRanges.stream()
                    .anyMatch(timeRange -> threadSnapshot.getTimestamp().after(timeRange.getStart()) && threadSnapshot.getTimestamp().before(timeRange.getEnd()));
            if (withinTimeRange) {
                threadSnapshots.add(threadSnapshot);
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Check if the file exists and is readable
    if (!file.exists() || !file.canRead()) {
        throw new IOException("File does not exist or is not readable");
    }

    // Check if the time ranges are valid
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges must not be null or empty");
    }

    // Parse the thread snapshots from the file
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Parse the line as a thread snapshot
            ThreadSnapshot threadSnapshot = ThreadSnapshot.parseFromString(line);
            if (threadSnapshot != null) {
                // Check if the thread snapshot is within the time range
                long timestamp = threadSnapshot.getTimestamp();
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                        threadSnapshots.add(threadSnapshot);
                    }
                }
            }
        }
    }

    return threadSnapshots;
}

